package stream

import "strings"

// tokenizePlaylist returns body with every URI it references carrying the
// given media token as a query parameter: plain URI lines (segments, variant
// playlists) and URI="..." attributes on tag lines (EXT-X-MAP inits,
// EXT-X-MEDIA renditions). Published playlists contain bare relative URIs —
// correct against a client that attaches the media_token cookie, but a
// cookie-less client (TV webviews splitting fetches across a native HTTP
// stack with no cookie jar, incident 2026-10-31) meets 401 on every segment.
// Embedding the already-validated requesting token makes the playlist
// self-authorizing: any client that could fetch it can fetch everything it
// references. Absolute URIs (any scheme) and URIs already carrying a
// `token=` parameter are left untouched, so the rewrite is idempotent and
// never rewrites foreign hosts.
func tokenizePlaylist(body []byte, token string) []byte {
	if token == "" {
		return body
	}
	lines := strings.Split(string(body), "\n")
	for i, line := range lines {
		cr := ""
		l := line
		if strings.HasSuffix(l, "\r") {
			l = strings.TrimSuffix(l, "\r")
			cr = "\r"
		}
		if l == "" {
			continue
		}
		if strings.HasPrefix(l, "#") {
			lines[i] = tokenizeURIAttrs(l, token) + cr
			continue
		}
		lines[i] = withTokenParam(l, token) + cr
	}
	return []byte(strings.Join(lines, "\n"))
}

// tokenizeURIAttrs rewrites every URI="..." attribute value on one tag line,
// leaving the rest of the line byte-identical. An unterminated value is left
// untouched (the pack lane always terminates).
func tokenizeURIAttrs(line, token string) string {
	const marker = `URI="`
	var b strings.Builder
	rest := line
	for {
		i := strings.Index(rest, marker)
		if i < 0 {
			b.WriteString(rest)
			return b.String()
		}
		j := i + len(marker)
		k := strings.IndexByte(rest[j:], '"')
		if k < 0 {
			b.WriteString(rest)
			return b.String()
		}
		k += j
		b.WriteString(rest[:j])
		b.WriteString(withTokenParam(rest[j:k], token))
		b.WriteByte('"')
		rest = rest[k+1:]
	}
}

// withTokenParam appends the token as a query parameter to a playlist URI —
// `?token=` on a bare URI, `&token=` after an existing query — unless the URI
// is empty, absolute (a scheme), or already carries the parameter.
func withTokenParam(uri, token string) string {
	if uri == "" || strings.Contains(uri, "://") || strings.Contains(uri, "token=") {
		return uri
	}
	sep := "?"
	if strings.Contains(uri, "?") {
		sep = "&"
	}
	return uri + sep + "token=" + token
}
